"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { supabase } from "@/lib/supabase";
import { Loader2, ArrowRight, Store } from "lucide-react";

export default function StartSellingPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  const go = async () => {
    setLoading(true);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        router.push("/login");
        return;
      }

      await supabase
        .from("profiles")
        .update({
          is_seller: true,
          prestige_weight: 2,
          subscription_plan: "standard",
          subscription_status: "active",
          onboarding_step: "seller_identity",
          updated_at: new Date().toISOString(),
        })
        .eq("id", user.id);

      router.push("/onboarding/seller/identity?upgrade=1");
      router.refresh();
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-xl space-y-8">
      <div className="rounded-[2.5rem] bg-gray-900 text-white p-10 shadow-2xl">
        <div className="w-14 h-14 rounded-2xl bg-white/10 flex items-center justify-center mb-6">
          <Store className="text-emerald-400" size={32} />
        </div>
        <h1 className="text-3xl font-black uppercase tracking-tighter leading-none">Start selling</h1>
        <p className="text-gray-400 font-medium text-sm mt-4 leading-relaxed">
          Standard storefront is free. We&apos;ll walk you through creating your store on StoreLink — inventory, orders, and checkout in one place.
        </p>
        <button
          type="button"
          disabled={loading}
          onClick={go}
          className="mt-10 w-full py-5 rounded-2xl bg-emerald-500 text-white font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-2 hover:bg-emerald-400 transition disabled:opacity-50"
        >
          {loading ? <Loader2 className="animate-spin" size={18} /> : <>Continue to store setup <ArrowRight size={18} /></>}
        </button>
      </div>
      <p className="text-xs text-gray-500 font-medium text-center">
        Already started? You’ll be redirected to your storefront wizard.
      </p>
    </div>
  );
}
